 else{$admin=query('SELECT * FROM admins WHERE email=?',[trim((string)($_POST['email']??''))])->fetch();if($admin&&password_verify((string)($_POST['password']??''),$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));admin_remember_device((int)$admin['id'],$admin['password_hash']);query('DELETE FROM login_attempts WHERE ip_hash=?',[$ip]);redirect('admin/index.php');}
